"""Fault injection across both stores; save order is independent of day/wall clock."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,hashlib
ROOT=Path(__file__).resolve().parents[1];source=(ROOT/'assets/game.js').read_bytes();sha=hashlib.sha256(source).hexdigest()
probe='''window.__storageTest={ready:()=>saveStorePromise,flush:async()=>{await saveStorePromise;await saveWrites;},save:()=>save(),found:()=>start(true),head:()=>({epoch:saveEpoch,order:saveOrder,town:saveTown,revision:saveRevision,ok:autoSaveOK}),records:()=>localSaveCandidates().concat(saveCandidates).map(e=>({order:e.order,town:e.town,revision:e.revision,day:JSON.parse(e.payload).day})),crash:()=>{G=null;saveEpoch++},legacy:payload=>({payload,checksum:checksum(payload)}),backup:e=>readSaveEnvelope(e),remoteHead:()=>{const e={...saveCandidates[0],order:10000};e.checksum=checksum([e.format,e.order,e.town,e.revision,e.payload].join('|'));return e}};'''
script=source.decode().replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js')
results=[]
def record(value):
 results.append(value);print(value,flush=True)
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 def page(c):
  p=c.new_page();p.route('**/game.js',lambda route:route.fulfill(body=script,content_type='application/javascript'));p.goto((ROOT/'assets/index.html').as_uri());p.evaluate('__storageTest.ready()');return p
 def fresh():
  c=b.new_context();p=page(c);p.locator('#townSeed').fill('42');p.locator('#newTown').click();p.locator('#pause').click();p.evaluate('__storageTest.flush()');return c,p
 def reload(c,p):
  p.close(run_before_unload=False);p=page(c);p.locator('#continue').click();p.wait_for_function('document.querySelector("#welcome").style.display==="none"');p.locator('#pause').click();return p
 # Quota leaves the primary old; the newer indexed copy must win on cold Continue.
 c,p=fresh();p.evaluate('__townTest.step(40);__townArchive.suspend()');p.evaluate('__storageTest.flush()');p.evaluate("Storage.prototype.setItem=function(){throw new DOMException('Injected quota','QuotaExceededError')};__townTest.step(20);__townArchive.suspend()");p.evaluate('__storageTest.flush()');p=reload(c,p);assert p.evaluate('__townTest.get().day')==61;record('quota: newer indexed day61 beats local day41')
 # Same-day changes have distinct revisions; day and wall time never rank snapshots.
 before=p.evaluate('__storageTest.head()');p.evaluate('Date.now=()=>1');p.locator('[data-panel=policies]').click();original=p.evaluate('__townTest.get().policy.imports');p.locator('#tradeToggle').click();p.locator('#enactPolicy').click();p.evaluate('__storageTest.flush()');after=p.evaluate('__storageTest.head()');assert after['order']>before['order'] and after['revision']>before['revision'];p=reload(c,p);assert p.evaluate('__townTest.get().policy.imports')!=original;record('same-day policy revision survives clock rollback')
 # A new lower-day town must replace an older much longer-lived town.
 old=p.evaluate('__storageTest.head()');p.evaluate('__storageTest.found()');p.locator('#pause').click();p.evaluate('__storageTest.flush()');new=p.evaluate('__storageTest.head()');assert new['town']!=old['town'] and new['order']>old['order'];p=reload(c,p);assert p.evaluate('__townTest.get().day')==1 and p.evaluate('__storageTest.head().town')==new['town'];record('new founding day1 wins over prior day61 by timeline/order');c.close()
 # Corrupt metadata and payload, even with a far-future simulated date, cannot win.
 c,p=fresh();p.evaluate('__townTest.step(30);__townArchive.suspend()');p.evaluate('__storageTest.flush()');expected=p.evaluate('__townTest.get().day');p.evaluate("const e=JSON.parse(localStorage.getItem('townledger-v6'));e.order=9000000000000;e.payload=e.payload.replace('\"day\":31','\"day\":99999');localStorage.setItem('townledger-v6',JSON.stringify(e))");p=reload(c,p);assert p.evaluate('__townTest.get().day')==expected;record('corrupted payload/chronology rejected in favor of valid indexed copy');c.close()
 # Interrupted IDB write: abort after put; intact newer local copy remains authoritative.
 c,p=fresh();p.evaluate('''window.__realOpen=indexedDB.open.bind(indexedDB);indexedDB.open=function(...args){const req=__realOpen(...args);req.addEventListener('success',()=>{const db=req.result,real=db.transaction.bind(db);db.transaction=function(...a){const tx=real(...a);if(a[1]==='readwrite'){const os=tx.objectStore.bind(tx);tx.objectStore=function(name){const store=os(name),put=store.put.bind(store);store.put=function(...v){const r=put(...v);tx.abort();return r};return store}}return tx}});return req};__townTest.step(15);__townArchive.suspend()''');p.evaluate('__storageTest.flush()');stored=p.evaluate("() => new Promise(resolve=>{const r=indexedDB.open('townledger-save',1);r.onsuccess=()=>{const db=r.result,t=db.transaction('saves'),g=t.objectStore('saves').get('latest');g.onsuccess=()=>resolve(JSON.parse(g.result.payload).day);t.oncomplete=()=>db.close()}})");assert stored==1,stored;p=reload(c,p);assert p.evaluate('__townTest.get().day')==16;record('aborted indexed transaction recovers newer local copy');c.close()
 # A failed backup-slot write must not block a primary replacement that fits.
 c,p=fresh();p.evaluate("window.__set=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==='townledger-v6-backup')throw new DOMException('Injected backup quota','QuotaExceededError');return __set.call(this,k,v)};__townTest.step(4);__townArchive.suspend()");p.evaluate('__storageTest.flush()');assert p.evaluate("JSON.parse(JSON.parse(localStorage.getItem('townledger-v6')).payload).day")==5;record('backup quota failure does not block primary replacement');c.close()
 # Both stores unavailable: no false success and the active town is retained.
 c,p=fresh();saved=p.evaluate('__townTest.save()');p.evaluate("Storage.prototype.setItem=function(){throw Error('Injected denied storage')};Object.defineProperty(window,'indexedDB',{configurable:true,value:{open(){throw Error('Injected indexed store failure')}}});__townTest.step(5)");assert not p.evaluate('__storageTest.save()');assert not p.evaluate('__storageTest.head().ok');assert p.evaluate('__townTest.get().day')==6;assert p.evaluate('__townTest.validate().ok');record('both store failures report failure without replacing active town');c.close()
 # A delayed open from an old town cannot commit after an imported replacement.
 c,p=fresh();archive=p.evaluate('__townTest.save()');p.evaluate('''window.__held=null;window.__open=indexedDB.open.bind(indexedDB);let heldOnce=false;Object.defineProperty(window,'indexedDB',{configurable:true,value:{open(...args){if(heldOnce)return __open(...args);heldOnce=true;const real=__open(...args),fake={};real.onupgradeneeded=e=>fake.onupgradeneeded?.(e);real.onerror=e=>fake.onerror?.(e);real.onsuccess=e=>{fake.result=real.result;window.__held=()=>fake.onsuccess?.(e)};return fake}}});__townTest.step(100);__townArchive.suspend();void 0''');p.wait_for_function("typeof window.__held==='function'");p.evaluate('''raw=>{const imported=JSON.parse(raw);if(!__townArchive.restore(JSON.stringify(imported)))throw Error('Import failed');window.__held()}''',archive);p.evaluate('__storageTest.flush()');head=p.evaluate('__storageTest.head()');p=reload(c,p);assert p.evaluate('__townTest.get().day')==1 and p.evaluate('__storageTest.head().town')==head['town'];record('delayed old-town callback cannot overwrite imported day1');c.close()
 # Reconcile a previously unseen newer head without using the wall clock.
 c,p=fresh();remote=p.evaluate('__storageTest.remoteHead()');p.evaluate("e=>new Promise(resolve=>{const r=indexedDB.open('townledger-save',1);r.onsuccess=()=>{const db=r.result,t=db.transaction('saves','readwrite');t.objectStore('saves').put(e,'latest');t.oncomplete=()=>{db.close();resolve()}}})",remote);p.evaluate('__townTest.step(9);__townArchive.suspend()');p.evaluate('__storageTest.flush()');assert p.evaluate('__storageTest.head().order')>10000;p=reload(c,p);assert p.evaluate('__townTest.get().day')==10;record('late newer store head promotes active save atomically');c.close()
 # Legacy raw IndexedDB records migrate without changing their deterministic payload.
 c,p=fresh();raw=p.evaluate('__townTest.save()');p.evaluate("raw=>new Promise(resolve=>{const r=indexedDB.open('townledger-save',1);r.onsuccess=()=>{const db=r.result,t=db.transaction('saves','readwrite');t.objectStore('saves').put(raw,'latest');t.oncomplete=()=>{db.close();localStorage.removeItem('townledger-v6');localStorage.removeItem('townledger-v6-backup');resolve()}}})",raw);p.evaluate('__storageTest.crash()');p=reload(c,p);assert p.evaluate('__townTest.get().day')==1;assert p.evaluate('__storageTest.save()');p.evaluate('__storageTest.flush()');assert p.evaluate("JSON.parse(localStorage.getItem('townledger-v6')).format")==1;record('legacy raw indexed archive migrates to integrity-bound chronology');c.close()
 # Two different pre-chronology copies cannot be ranked by simulated day.
 c,p=fresh();early=p.evaluate('__townTest.save()');p.evaluate('__townTest.step(40);__townArchive.suspend()');p.evaluate('__storageTest.flush()');late=p.evaluate('__townTest.save()');envelope=p.evaluate('s=>__storageTest.legacy(s)',late);p.evaluate("e=>{localStorage.setItem('townledger-v6',JSON.stringify(e));localStorage.removeItem('townledger-v6-backup')}",envelope);p.evaluate("raw=>new Promise(resolve=>{const r=indexedDB.open('townledger-save',1);r.onsuccess=()=>{const db=r.result,t=db.transaction('saves','readwrite');t.objectStore('saves').put(raw,'latest');t.oncomplete=()=>{db.close();resolve()}}})",early);p.evaluate('__storageTest.crash()');p.close(run_before_unload=False);p=page(c);p.locator('#continue').click();assert p.locator('#eventDialog').is_visible();assert 'no save chronology' in p.locator('#eventText').inner_text();p.locator('#eventDefer').click();assert p.evaluate("JSON.parse(JSON.parse(localStorage.getItem('townledger-v6')).payload).day")==41;p.locator('#continue').click();p.locator('[data-event-choice="1"]').click();p.wait_for_function('document.querySelector("#welcome").style.display==="none"');p.locator('#pause').click();p.evaluate('__storageTest.flush()');assert p.evaluate('__townTest.get().day')==1;record('ambiguous legacy copies offer cancel/recovery instead of guessing from day');c.close()
 # Invalid restore leaves the persistence timeline and game byte-for-byte intact.
 c,p=fresh();head=p.evaluate('__storageTest.head()');raw=p.evaluate('__townTest.save()');assert not p.evaluate('__townArchive.restore("{broken")');assert p.evaluate('__townTest.save()')==raw and p.evaluate('__storageTest.head()')==head;record('invalid import preserves game and persistence head');c.close();b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-persistence';out.mkdir(exist_ok=True);(out/'faults.json').write_text(json.dumps({'source_sha256':sha,'checks':results},indent=2)+'\n');print('PASS',json.dumps(results))
